import{_ as r,C as s,o as l,c as d,j as t,a,E as o,a3 as n}from"./chunks/framework.CZBGEXos.js";const v=JSON.parse('{"title":"Alerts","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/alerts.md","filePath":"en/tools/alerts.md"}'),h={name:"en/tools/alerts.md"};function c(u,e,p,m,g,f){const i=s("Screenshot");return l(),d("div",null,[e[0]||(e[0]=t("h1",{id:"alerts",tabindex:"-1"},[a("Alerts "),t("a",{class:"header-anchor",href:"#alerts","aria-label":'Permalink to "Alerts"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Alerts watches for two things at once and shows them in a single feed:",-1)),e[2]||(e[2]=t("ol",null,[t("li",null,[t("strong",null,"Price deviation"),a(" — the same asset priced differently on different exchanges right now.")]),t("li",null,[t("strong",null,"New listings"),a(" — a token that just started trading on a monitored exchange.")])],-1)),o(i,{src:"alerts",alt:"The Alerts window with two deviation cards, one dimmed, and the liquidation tape docked right",caption:"The Alerts window — the second card is dimmed; the liquidation tape is docked right"}),e[3]||(e[3]=n('<h2 id="reading-the-window" tabindex="-1">Reading the window <a class="header-anchor" href="#reading-the-window" aria-label="Permalink to &quot;Reading the window&quot;">​</a></h2><h3 id="titlebar" tabindex="-1">Titlebar <a class="header-anchor" href="#titlebar" aria-label="Permalink to &quot;Titlebar&quot;">​</a></h3><p>The titlebar summarises the settings in force: the chart timeframe, the <strong>Decorrelation</strong> threshold, <strong>Max Age</strong>, <strong>Max Spread</strong> (when set) and, when the volume filter is on, <strong>Min 24h Vol</strong>.</p><h3 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to &quot;Order&quot;">​</a></h3><p>Cards are ordered newest first, by <strong>when the spread opened</strong>. A card keeps its position as its numbers update, so the feed does not reshuffle under you while you&#39;re reading it.</p><h3 id="a-deviation-card" tabindex="-1">A deviation card <a class="header-anchor" href="#a-deviation-card" aria-label="Permalink to &quot;A deviation card&quot;">​</a></h3><ul><li><strong>Symbol</strong> — click to copy it to your clipboard; briefly reads <code>Copied!</code>.</li><li><strong>Spread</strong> — the live maximum price spread across exchanges, as a percentage.</li><li><strong>Age</strong> — how long the spread has been at or above your threshold, e.g. <code>12m</code> or <code>3h</code>.</li><li><strong>Legend</strong> — one entry per exchange holding the ticker: a colored dot matching its line on the chart, the exchange name, and its volume. Hovering an entry shows that exchange&#39;s exact price and volume.</li><li><strong>Mini chart</strong> — one price line per exchange, so you can see whether the gap is opening, closing, or holding.</li><li><strong>Expand button</strong> — opens the card fullscreen; see <a href="#fullscreen">Fullscreen</a>.</li></ul><h4 id="dimmed-cards" tabindex="-1">Dimmed cards <a class="header-anchor" href="#dimmed-cards" aria-label="Permalink to &quot;Dimmed cards&quot;">​</a></h4><p>A card turns <strong>dimmed</strong> when its live spread drops back below your <a href="#minimum-decorrelation">minimum decorrelation</a>. The spread is not over yet — the server keeps it open until it has stayed below the threshold for <strong>10 minutes</strong>. If it widens again, the card lights back up and keeps its age. If not, it drops out of the feed.</p><p>The alert sound plays once per new spread, not again when a dimmed card comes back.</p><h4 id="how-the-spread-is-calculated" tabindex="-1">How the spread is calculated <a class="header-anchor" href="#how-the-spread-is-calculated" aria-label="Permalink to &quot;How the spread is calculated&quot;">​</a></h4><p>The percentage is <code>(highest price − lowest price) ÷ lowest price × 100</code>, taken across every exchange currently reporting that ticker.</p><p>This figure is <strong>live</strong>. It is recomputed continuously from the same exchange websockets that feed the chart lines and refreshed about twice a second, so it tracks the current gap rather than the gap at the moment the alert fired.</p><div class="warning custom-block"><p class="custom-block-title">A spread is not a guaranteed profit</p><p>The number is a difference between two quoted prices. It says nothing about whether you could actually trade it — order book depth, fees, funding, transfer time and withdrawal availability are not part of the calculation, and a visible gap can close before an order fills. Treat it as a signal to look, not a result.</p></div><p>The chart is deliberately zoomed in with tight price margins, because the gap between exchange lines is usually small relative to the price and would be invisible at a normal scale.</p><h3 id="fullscreen" tabindex="-1">Fullscreen <a class="header-anchor" href="#fullscreen" aria-label="Permalink to &quot;Fullscreen&quot;">​</a></h3><p>The expand button opens a deviation card at full window size: the same price lines per exchange, the legend, the live spread and its age. The timeframe picker works like the fullscreen view in Knives and Monitor, and starred timeframes are shared with them. Press <kbd>Esc</kbd> or the close button to exit.</p><h3 id="a-new-listing-card" tabindex="-1">A new listing card <a class="header-anchor" href="#a-new-listing-card" aria-label="Permalink to &quot;A new listing card&quot;">​</a></h3><p>Listing cards look different from deviation cards: a <strong>NEW</strong> tag, the symbol (also click-to-copy), and the listing time. They share the feed and the same card limit as deviation alerts.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Open the <strong>Alerts</strong> tab in the main window.</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-cards" tabindex="-1">Max cards <a class="header-anchor" href="#max-cards" aria-label="Permalink to &quot;Max cards&quot;">​</a></h4><p>How many cards the feed shows at once. Range <strong>3 to 50</strong>, default 9.</p><p>The limit is applied after deviation and listing alerts are merged and sorted, so both types compete for the same slots.</p><h4 id="chart-timeframe" tabindex="-1">Chart timeframe <a class="header-anchor" href="#chart-timeframe" aria-label="Permalink to &quot;Chart timeframe&quot;">​</a></h4><p>The candle interval used for the price lines inside deviation cards. Options: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code>, <code>1w</code>. Default <code>1m</code>.</p><p>This only changes the chart. It does not change how the spread is calculated or which alerts qualify.</p><h3 id="alert-settings" tabindex="-1">Alert settings <a class="header-anchor" href="#alert-settings" aria-label="Permalink to &quot;Alert settings&quot;">​</a></h3><h4 id="minimum-decorrelation" tabindex="-1">Minimum decorrelation <a class="header-anchor" href="#minimum-decorrelation" aria-label="Permalink to &quot;Minimum decorrelation&quot;">​</a></h4><p>The spread a ticker must reach before it produces an alert. Range <strong>1% to 10%</strong> in 0.5% steps, default 1%.</p><p>A spread that falls back below this value is <a href="#dimmed-cards">dimmed</a>, not removed at once. It leaves the feed after 10 minutes below the threshold.</p><h4 id="max-spread" tabindex="-1">Max spread % <a class="header-anchor" href="#max-spread" aria-label="Permalink to &quot;Max spread %&quot;">​</a></h4><p>Hides spreads wider than this. Default <strong>off</strong> (empty). The − / + buttons step by 5%, or type any value.</p><p>A spread of hundreds of percent is almost never a real opportunity. Usually it is two different coins listed under the same ticker on different exchanges. <strong>50%</strong> is a good starting point.</p><h4 id="max-spread-age" tabindex="-1">Max spread age <a class="header-anchor" href="#max-spread-age" aria-label="Permalink to &quot;Max spread age&quot;">​</a></h4><p>Hides spreads that have been open longer than this. Steps: <strong>Off</strong>, 30m, 1h, 2h, 4h, 8h, 12h, 1d, 2d, 3d, 7d. Default Off.</p><p>A gap that has stayed open for days is usually structural — a suspended withdrawal, a different token — rather than something that will close.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="alert-sound" tabindex="-1">Alert sound <a class="header-anchor" href="#alert-sound" aria-label="Permalink to &quot;Alert sound&quot;">​</a></h4><p>Plays a sound when a new deviation alert appears. On by default.</p><h4 id="listing-alert-sound" tabindex="-1">Listing alert sound <a class="header-anchor" href="#listing-alert-sound" aria-label="Permalink to &quot;Listing alert sound&quot;">​</a></h4><p>Plays a sound when a new token is listed. On by default.</p><p>The two are independent — you can have listings audible and deviations silent, or the reverse.</p><h3 id="volume-filter" tabindex="-1">Volume filter <a class="header-anchor" href="#volume-filter" aria-label="Permalink to &quot;Volume filter&quot;">​</a></h3><h4 id="enable-volume-filter" tabindex="-1">Enable volume filter <a class="header-anchor" href="#enable-volume-filter" aria-label="Permalink to &quot;Enable volume filter&quot;">​</a></h4><p>Filters deviation alerts by 24-hour trading volume. Off by default.</p><div class="info custom-block"><p class="custom-block-title">It takes two</p><p>A deviation alert needs <strong>at least two exchanges</strong> above the minimum volume to pass the filter. That is deliberate: a price gap is only meaningful if both sides of it have real trading behind them.</p></div><p>This filter applies to deviation alerts only. New listing alerts are not filtered by volume — a token that just listed has no meaningful volume history.</p><h4 id="minimum-24h-volume" tabindex="-1">Minimum 24h volume <a class="header-anchor" href="#minimum-24h-volume" aria-label="Permalink to &quot;Minimum 24h volume&quot;">​</a></h4><p>The 24-hour volume, in USD, an exchange needs for its side of a deviation to count. Type the amount; default <strong>$1,000,000</strong>.</p><p>Greyed out unless the volume filter is enabled.</p><div class="info custom-block"><p class="custom-block-title">All of these filters run on the server</p><p>Threshold, max spread %, max age and the volume filter are all applied on the server, so a hidden spread never reaches the app at all. Changing a value takes effect within a second.</p></div><h2 id="liquidation-tape" tabindex="-1">Liquidation tape <a class="header-anchor" href="#liquidation-tape" aria-label="Permalink to &quot;Liquidation tape&quot;">​</a></h2><p>Alerts can also carry a live tape of <strong>forced position closes</strong> — a separate feed from the deviation and listing cards, shown in its own strip alongside them.</p><p>It is <strong>on by default</strong>. Liquidations come from <strong>Binance</strong> and <strong>Bybit</strong> perpetuals — the venues that publish them.</p><h3 id="reading-the-tape" tabindex="-1">Reading the tape <a class="header-anchor" href="#reading-the-tape" aria-label="Permalink to &quot;Reading the tape&quot;">​</a></h3><p>The header shows <code>LIQUIDATIONS</code> and, when anything has arrived recently, a running figure — the <strong>total liquidated in the last 60 seconds</strong>.</p><p>Each row is one event, newest at the top:</p><table tabindex="0"><thead><tr><th>Part</th><th>Meaning</th></tr></thead><tbody><tr><td>Time</td><td>When it printed</td></tr><tr><td>Coloured dot</td><td>Which exchange, in that exchange&#39;s colour</td></tr><tr><td>Symbol</td><td>With the <code>USDT</code> / <code>USDC</code> suffix stripped</td></tr><tr><td>Amount</td><td>Notional value of that single liquidation</td></tr></tbody></table><p>The row&#39;s background bar scales with size, so big events are visible without reading the number. <strong>Click a row to copy its symbol.</strong></p><p>Hovering spells the event out — venue, <code>long liquidated → forced sell</code> or <code>short liquidated → forced buy</code>, quantity and price.</p><div class="warning custom-block"><p class="custom-block-title">Colour follows the pressure, not the word</p><p>A liquidated <strong>long</strong> is a forced <strong>sell</strong>; a liquidated <strong>short</strong> is a forced <strong>buy</strong>. The tape colours by that resulting pressure, matching the liquidation diamonds in the <a href="/manual/en/customize/majors.html#liquidations-—-diamonds">majors overlay</a>.</p></div><p>Before the first event arrives the tape reads <code>waiting…</code> rather than sitting blank.</p><h3 id="moving-and-resizing-it" tabindex="-1">Moving and resizing it <a class="header-anchor" href="#moving-and-resizing-it" aria-label="Permalink to &quot;Moving and resizing it&quot;">​</a></h3><p><strong>Drag the <code>LIQUIDATIONS</code> header</strong> to dock the tape to any edge — left, right, top or bottom. Left and right give a column of rows; top and bottom give a horizontal strip. Default is right.</p><p>Drag the gutter between the tape and the cards to resize it.</p><p>If you shrink the window far enough the tape hides itself rather than crowding out the alert cards.</p><h3 id="settings-1" tabindex="-1">Settings <a class="header-anchor" href="#settings-1" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>Open the <strong>Alerts</strong> tab in the main window.</p>',70)),o(i,{src:"liquidations-settings",alt:"The liquidation settings in the Alerts tab",caption:"Alerts settings — liquidations"}),e[4]||(e[4]=n('<h4 id="enable-liquidation-tape" tabindex="-1">Enable liquidation tape <a class="header-anchor" href="#enable-liquidation-tape" aria-label="Permalink to &quot;Enable liquidation tape&quot;">​</a></h4><p>Shows forced position closes as they happen. <strong>On by default.</strong> Everything below is inert while this is off.</p><h4 id="minimum-size" tabindex="-1">Minimum size <a class="header-anchor" href="#minimum-size" aria-label="Permalink to &quot;Minimum size&quot;">​</a></h4><p>The size of a single liquidation, in USD. Range <strong>$5,000 to $1,000,000</strong> in $5,000 steps, default $50,000. It applies to every venue that does not have its own size.</p><p>$5,000 is the server&#39;s own floor: nothing smaller is stored, so the minimum setting already means &quot;everything there is&quot;.</p><h4 id="per-venue-settings" tabindex="-1">Per-venue settings <a class="header-anchor" href="#per-venue-settings" aria-label="Permalink to &quot;Per-venue settings&quot;">​</a></h4><p>Below the minimum size there is one block each for <strong>Binance</strong> and <strong>Bybit</strong>:</p><ul><li>A switch to mute that venue entirely.</li><li><strong>Size on this venue</strong> — its own minimum size. At the far left it reads <code>global $50K</code> and follows the minimum size above.</li></ul><p>$50K is routine on Binance but can be a large event elsewhere, so giving each venue its own size keeps one venue from drowning out the other. If both venues are muted, the app warns you that nothing can arrive.</p><h4 id="minimum-24h-turnover" tabindex="-1">Minimum 24h turnover <a class="header-anchor" href="#minimum-24h-turnover" aria-label="Permalink to &quot;Minimum 24h turnover&quot;">​</a></h4><p>Hides thin tickers by their 24-hour turnover. Range <strong>$0 to $50M</strong> in $1M steps, default 0 — shown as <code>off</code>, meaning no filtering.</p><div class="warning custom-block"><p class="custom-block-title">A non-zero value also hides unknown tickers</p><p>Any symbol whose 24h turnover is not yet known is hidden too, not just the genuinely thin ones. On a freshly opened window that can mean noticeably fewer events until turnover figures are in.</p></div><h4 id="blacklist" tabindex="-1">Blacklist <a class="header-anchor" href="#blacklist" aria-label="Permalink to &quot;Blacklist&quot;">​</a></h4><p>Symbols to never show. Type one and press <kbd>Enter</kbd> to add it; <strong>Clear all</strong> empties the list.</p><p>Useful for the handful of tickers that liquidate constantly and would otherwise dominate the tape.</p><h4 id="rows-kept" tabindex="-1">Rows kept <a class="header-anchor" href="#rows-kept" aria-label="Permalink to &quot;Rows kept&quot;">​</a></h4><p>How many events the tape holds before dropping the oldest. Range <strong>20 to 300</strong> in steps of 20, default 100.</p><h4 id="liquidation-sound" tabindex="-1">Liquidation sound <a class="header-anchor" href="#liquidation-sound" aria-label="Permalink to &quot;Liquidation sound&quot;">​</a></h4><p>Plays a sound when a liquidation arrives. <strong>Off by default.</strong></p><p>Note that this fires on <em>every</em> event that passes your filters — with a low minimum size on a busy market that is a lot of sound. Raise <strong>Minimum size</strong> first, then turn this on.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/manual/en/tools/knives.html">Knives</a> — single-exchange price moves rather than cross-exchange gaps. Knives also shows a <strong>NEW</strong> badge for fresh listings on its ticker cards.</li><li><a href="/manual/en/tools/monitor.html">Monitor</a> — ranked market overview</li></ul>',22))])}const w=r(h,[["render",c]]);export{v as __pageData,w as default};
